def safe_json(x):return json.dumps(x,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
def inline(s):
 s=html.escape(s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
 def render_link(m):
  target=m.group(2);base=target.split('#')[0]
  if base in viewer_sections:target='#'+viewer_sections[base]
  return '<a href="'+target+'"'+(' target="_blank" rel="noopener noreferrer"' if target.startswith('https://') else '')+'>'+m.group(1)+'</a>'
 s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',render_link,s)
 return s
def markdown(text):
 result=[];paragraph=[];code=[];in_code=False;table=[];ordered=[]
 def flush_p():
  if paragraph:result.append('<p>'+inline(' '.join(paragraph))+'</p>');paragraph.clear()
 def flush_t():
  if not table:return
  rows=[r for r in table if not re.match(r'^\|[\s:|-]+\|$',r)];cells=[r.strip('|').split('|') for r in rows]
  result.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+inline(c.strip())+'</th>' for c in cells[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c.strip())+'</td>' for c in row)+'</tr>' for row in cells[1:])+'</tbody></table></div>');table.clear()
 def flush_o():
  if ordered:
   result.append('<ol start="'+ordered[0][0]+'">'+''.join('<li>'+inline(item[1])+'</li>' for item in ordered)+'</ol>');ordered.clear()
 for line in text.splitlines():
  item=re.match(r'^(\d+)\.\s+(.*)',line) if not in_code else None
  if item:flush_p();flush_t();ordered.append((item[1],item[2]));continue
  flush_o()
  if line.startswith('```'):
   flush_p();flush_t()
   if in_code:result.append('<pre><code>'+html.escape('\n'.join(code))+'</code></pre>');code=[]
   in_code=not in_code;continue
  if in_code:code.append(line);continue
  if line.startswith('|'):flush_p();table.append(line);continue
  flush_t()
  if not line.strip():flush_p();continue
  if line.startswith('<a id='):continue
  h=re.match(r'^(#{1,6})\s+(.*)',line)
  if h:flush_p();level=min(len(h[1])+1,6);result.append(f'<h{level}>'+inline(h[2])+f'</h{level}>');continue
  if line.startswith('- '):flush_p();result.append('<p class="bullet">• '+inline(line[2:])+'</p>');continue
  if line.startswith('> '):flush_p();result.append('<blockquote>'+inline(line[2:])+'</blockquote>');continue
  paragraph.append(line)
 flush_p();flush_t();flush_o();return '\n'.join(result)

