app='''<section id="projects" hidden><h2>222 проекта и обращения пользователей</h2><p class="notice">Для каждой записи получены README и тело выбранного обращения; у 187 найден файл сборки. Это документарный обзор. Классификация и схемы — анализ, обращения не воспроизводились. Смежные инструменты и SDK помечены отдельно.</p><p><a href="PROJECTS.md">Полные карточки</a> · <a href="research/registry.csv">CSV</a> · <a href="research/registry.json">Доказательства JSON</a></p><div class="tools"><input id="projectQuery" aria-label="Поиск проекта" placeholder="Название, технология, тема"><select id="projectCategory" aria-label="Категория"><option value="">Все категории</option></select></div><p id="projectCount" class="meta"></p><div id="projectCards"></div><div class="pager"><button id="prev">Назад</button><span id="pageNumber"></span><button id="next">Далее</button></div></section>
<section id="cases" hidden><h2>Сценарии по этапам</h2><p class="notice">16 × 2000 = 32 000 параметризованных сценариев спецификации. Не выполненные продуктовые тесты. Не 32 000 независимо придуманных историй. Конкретные автоматические fixtures ещё требуют реализации.</p><p><a href="scenarios/gargantua-32000-scenarios.zip">Все сценарии: ZIP, JSONL и CSV</a> · <a href="scenarios/manifest.json">Покрытие и хеши</a></p><div class="case-selectors"><div><label for="stage">Этап</label><select id="stage"></select></div><div><label for="operation">Операция</label><select id="operation"></select></div><div><label for="fixture">Набор данных</label><select id="fixture"></select></div><div><label for="condition">Условие</label><select id="condition"></select></div></div><div id="caseCard" class="card case"></div></section>'''
js='''const registry=DATA.registry,model=DATA.model;const $=id=>document.getElementById(id);let page=0;
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function link(label,url){const a=el('a',label);a.href=url;if(url.startsWith('https://')){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function show(id){const target=document.getElementById(id);if(!target||!target.matches('main>section'))id='reassessment';document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('aside button').forEach(b=>b.classList.toggle('active',b.dataset.section===id));location.hash=id;}
document.querySelectorAll('aside button').forEach(b=>b.addEventListener('click',()=>{show(b.dataset.section);window.scrollTo(0,0);}));window.addEventListener('hashchange',()=>show(location.hash.slice(1)));show(location.hash.slice(1)||'reassessment');
for(const c of [...new Set(registry.map(p=>p.category))]){const o=el('option',c);o.value=c;$('projectCategory').append(o);}
function renderProjects(){const q=$('projectQuery').value.toLowerCase(),cat=$('projectCategory').value;const found=registry.filter(p=>(!cat||p.category===cat)&&[p.repository,p.category,p.readme_technology_mentions.join(' '),p.build_declarations.join(' '),p.feedback_themes.join(' ')].join(' ').toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(found.length/12));page=Math.min(page,pages-1);$('projectCards').replaceChildren();for(const p of found.slice(page*12,(page+1)*12)){const c=el('article',undefined,'card');c.append(el('span',p.id+' · '+p.category,'pill'),el('h3',p.repository),el('p',p.architecture_analysis),el('p','Данные сборки: '+(p.build_declarations.join(', ')||'полный стек не подтверждён'),'meta'),el('p','Преимущество подхода: '+p.advantage_analysis),el('p','Ограничение: '+p.limitation_analysis),el('p','Контекст обращения: «'+(p.feedback_excerpt||'См. первоисточник')+'…» (фрагмент заголовка)','meta'),el('p','Темы обращения (предварительная разметка): '+(p.feedback_themes.join(', ')||'нужна ручная классификация'),'meta'),el('p','Решение: '+p.lesson_analysis));const a=el('p');a.append(link('Проект',p.url),document.createTextNode(' · '),link('README',p.readme.url),document.createTextNode(' · '),link('Обращение',p.feedback_url));c.append(a);$('projectCards').append(c);}$('projectCount').textContent='Найдено '+found.length+' из '+registry.length;$('pageNumber').textContent=(page+1)+' / '+pages;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;}
$('projectQuery').addEventListener('input',()=>{page=0;renderProjects();});$('projectCategory').addEventListener('change',()=>{page=0;renderProjects();});$('prev').addEventListener('click',()=>{page--;renderProjects();});$('next').addEventListener('click',()=>{page++;renderProjects();});renderProjects();
model.stages.forEach((s,i)=>{const o=el('option',s.id+' — '+s.name);o.value=i;$('stage').append(o);});model.conditions.forEach((c,i)=>{const o=el('option',c.name);o.value=i;$('condition').append(o);});
function stageOptions(){const s=model.stages[Number($('stage').value)];$('operation').replaceChildren();$('fixture').replaceChildren();s.flows.forEach((f,i)=>{const o=el('option',String(i+1)+'. '+f);o.value=i;$('operation').append(o);});s.profiles.forEach((f,i)=>{const o=el('option',String(i+1)+'. '+f.split('|')[0]);o.value=i;$('fixture').append(o);});renderCase();}
function renderCase(){const s=model.stages[Number($('stage').value)],fi=Number($('operation').value),pi=Number($('fixture').value),ci=Number($('condition').value),p=s.profiles[pi].split('|'),c=model.conditions[ci];const id=s.id+'-'+String(fi*100+pi*10+ci+1).padStart(4,'0');const box=$('caseCard');box.replaceChildren(el('h3',id+' · '+s.flows[fi]),el('output','NOT_EXECUTED · спецификация проверки'),el('p','Данные: '+p[0]),el('p','Условие: '+c.name),el('h4','Порядок проверки'));const steps=el('ol');for(const v of ['Подготовить изолированный fixture с фиксированными правами, версиями и зависимостями.','Вызвать выбранную операцию с фиксированным operationId.','Ввести выбранное условие на границе этапа.','Проверить результат, индекс, файлы, журнал и отсутствие запрещённых эффектов.'])steps.append(el('li',v));box.append(steps,el('h4','Ожидается'),el('p',p[1]),el('p',c.expect),el('p','Инвариант: '+s.invariant),el('p','Приоритет: отмена/запрет до побочного действия → недействительный вход → доступность зависимостей и ресурсов → результат. Связь с домашним сервером и внешний интернет различаются.','meta'));}
$('stage').addEventListener('change',stageOptions);for(const id of ['operation','fixture','condition'])$(id).addEventListener('change',renderCase);stageOptions();'''
